//! Exact OUTPUT for records reach actual attribute-based paint.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn output_form_actual_app_native_writes_drive_exact_paint_and_preserve_interaction(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-output-form-accessor-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}output{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}output[for="A�z"]{background:#cc2244}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}label{position:absolute;left:20px;top:100px}</style><body><form id=owner><label id=label for=output>Result</label><output id=output for='A�z'>ready</output></form><form id=other></form><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change references</button><div id=destination></div><script>var output=document.getElementById('output'),attr=output.getAttributeNode('for'),labels=output.labels,tokens=output.htmlFor,classes=output.classList,round=0;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer event';var value=round===1?'A�z':round===0?'A\ud800z':'B\udfffz',watch=new MutationObserver(function(){}),old=attr.value;watch.observe(output,{attributes:true,attributeOldValue:true});if(round===1)document.getElementById('other').appendChild(output);else document.getElementById('owner').appendChild(output);tokens.value=value;var records=watch.takeRecords();var expected=document.getElementById(round===1?'other':'owner');if(output.form!==expected||Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'form').get.call(output)!==expected||output.htmlFor!==tokens||output.classList!==classes||classes.value!==''||tokens.value!==value||output.getAttributeNode('for')!==attr||attr.value!==value||records.length!==1||records[0].oldValue!==old||output.matches('[for="A�z"]')!==(round===1)||output.labels!==labels||labels.length!==1||labels[0]!==document.getElementById('label')||labels[0].control!==output||labels[0].form!==expected)throw 'actual exact for records and independent label association';watch.disconnect();document.title='Output for '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0xcc2244);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Output for {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],if round==1{0xcc2244}else{0x114455});let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);}
}
